#[kani::proof]
    #[kani::unwind(8)]
    fn op121_descending_blocks() {
        let mut block = 6usize;
        let mut seen = 1u8 << 6;
        while block > 0 {
            block -= 1;
            assert!(block < 6);
            assert_eq!(seen & (1 << block), 0);
            seen |= 1 << block;
        }
        assert_eq!(seen, 127);
    }

