fn linear_step(point:&[QM31;10],variable:usize,suffix:QM31,weighted:QM31)->(QM31,QM31) {
    let suffix=suffix.add(point[variable]);
    let weighted=if variable!=0 {weighted.add(suffix)} else {weighted};
    (suffix,weighted)
}

fn linear_step(point:&[QM31;10], variable:usize, mut suffix:QM31, mut weighted:QM31)->(QM31,QM31) {
    suffix = suffix.add(point[variable]);
        if variable != 0 {
            weighted = weighted.add(suffix);
        }
    (suffix,weighted)
}

